import sys; sys.path.insert(0,'/tmp')
from lib import *
from collections import defaultdict
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
docs=[d for d in load('DocumentReference.ndjson') if 'subject' in d]
enc={e['id']:e for e in load('Encounter.ndjson')}
loc={l['id']:l['name'] for l in load('Location.ndjson')}
byp=defaultdict(list)
for d in docs: byp[pid(d)].append(d)
ecgs=defaultdict(list)
for e in json.load(open('ecgs.json'))['ecgs']: ecgs[e['patient']].append(e)
for p,ds in byp.items():
    ds.sort(key=lambda d:d['date'])
    with open(f'dossier/{p}.txt','w') as f:
        pt=pats[p]
        f.write(f"PATIENT {p} mrn={pt['identifier'][0]['value']} dob={pt['birthDate']} sex={pt['gender']} deceased={pt.get('deceasedDateTime')}\n")
        for e in sorted(ecgs[p], key=lambda x:x['time']):
            f.write(f"ECG {e['ecg']} {e['time']}\n")
        for d in ds:
            e=enc.get(d.get('context',{}).get('encounter',[{}])[0].get('reference','').split('/')[-1])
            ln = loc.get(e['location'][0]['location']['reference'].split('/')[-1],'?') if e and e.get('location') else '?'
            role=[x.get('valueCode') for x in d.get('extension',[]) if x['url'].endswith('author-role')]
            f.write(f"\n--- NOTE {d['id']} | {d['date']} | {d['type']['coding'][0]['display']} | role={role} | author={d.get('author',[{}])[0].get('display')} | loc={ln}\n")
            f.write(notetext(d)+"\n")
print(len(byp))
EOF
