import sys; sys.path.insert(0,'/tmp')
from lib import *
from collections import defaultdict
EVAL='2026-09-24T12:00:00-04:00'
ED='2026-09-24'
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
alive={k for k,v in pats.items() if not v.get('deceasedDateTime')}
enc={e['id']:e for e in load('Encounter.ndjson')}
loc={l['id']:l['name'] for l in load('Location.ndjson')}
def medname2(r):
    mr=r.get('medicationReference')
    if mr: return med.get(mr['reference'].split('/')[-1],'?')
    cc=r.get('medicationCodeableConcept',{})
    return cc.get('text') or (cc.get('coding',[{}])[0].get('display') or cc.get('coding',[{}])[0].get('code'))
rs=load('MedicationRequest.ndjson')
cur=defaultdict(list)
for r in rs:
    dr=r.get('dispenseRequest',{}).get('validityPeriod')
    if not dr: continue
    s=dr.get('start',''); e=dr.get('end','9999')
    if s[:10]<=ED<=e[:10]:
        p=pid(r)
        ee=enc.get(r.get('encounter',{}).get('reference','').split('/')[-1])
        ln=loc.get(ee['location'][0]['location']['reference'].split('/')[-1],'?') if ee and ee.get('location') else '?'
        di=r.get('dosageInstruction',[{}])[0]
        dose=di.get('text'); tim=di.get('timing',{}).get('code',{}).get('coding',[{}])[0].get('code')
        cur[p].append((medname2(r), r['status'], s[:10], e[:10], dose, tim, ln, r['id']))
import pickle
pickle.dump(dict(cur), open('cur.pkl','wb'))
print('patients with current orders:', len(cur))
AC=['warfarin','apixaban','rivaroxaban','dabigatran','edoxaban','enoxaparin','fondaparinux']
QT=['citalopram','escitalopram','haloperidol','methadone','amiodarone','sotalol','dofetilide']
for p in sorted(cur, key=lambda x: (x not in alive, x)):
    items=cur[p]
    flags=[i for i in items if any(a in (i[0] or '').lower() for a in AC+QT)]
    if flags:
        print(('ALIVE' if p in alive else 'DEAD '), p)
        for i in items: print('    ', i)
EOF

