def tend_tangent(f):
    M=f['M']; ri=f['ri']; off=f['off']; rrm=f['rrm']
    W0=off+int(0.04*FS)
    W1=int(min(len(M)-2, off+int(0.50*FS), ri+max(0.25,(rrm-0.12))*FS))
    if W1<=W0+5: W1=min(len(M)-2,W0+int(0.15*FS))
    best=None
    for li in range(12):
        x=sm(M[:,li],9)
        w=x[W0:W1]
        k=int(np.argmax(np.abs(w))); amp=float(w[k]); pos=W0+k
        if abs(amp)>abs(best[0]) if best else True:
            best=(amp,pos,li,x)
    amp,pos,li,x=best
    sign=np.sign(amp)
    d=np.gradient(x)*sign
    lo=pos+int(0.01*FS); hi=W1
    if hi<=lo+2: hi=min(len(x)-2,lo+3)
    j=lo+int(np.argmin(d[lo:hi])); slope=d[j]*sign
    if abs(slope)<1e-7: te=float(hi)
    else: te=j + (x[j]-0.0)/(-slope)
    te=float(min(max(te,pos+int(0.03*FS)),W1))
    return te, amp, pos, li
EOF
